/**
 * ConnectAxiRead: Creates hardware for reading CSR registers via AXI.
 *
 * This function creates hardware inside the current module that implements
 * a register-mapped AXI read interface. When addr.valid is asserted, the
 * address is sampled and one clock later data.valid is asserted with the
 * corresponding register value (or resp=2 for unknown addresses).
 *
 * @param addrBits  Number of address bits (also used as idBits)
 * @param readMap   Map from register name to (byte offset, UInt data)
 * @return          An AxiReadIO wire that can be bulk-connected (<>) to
 *                  the module's Flipped(AxiReadIO) port.
 */
def ConnectAxiRead(addrBits: Int, readMap: Map[String, (Int, UInt)]): AxiReadIO = {
  val dataBits = 32
  val idBits   = addrBits

  // Create the IO wire that will be returned for bulk connection
  val axi = Wire(new AxiReadIO(dataBits, dataBits, idBits))

  // --- Address channel (we accept every cycle) ---
  axi.addr.ready := true.B

  // --- Pipeline register: capture address + valid ---
  val rdPending  = RegInit(false.B)
  val rdAddr     = RegInit(0.U(dataBits.W))
  val rdId       = RegInit(0.U(idBits.W))

  when(axi.addr.valid) {
    rdPending := true.B
    rdAddr    := axi.addr.bits.addr
    rdId      := axi.addr.bits.id
  }.elsewhen(axi.data.valid && axi.data.ready) {
    rdPending := false.B
  }

  // --- Data channel: drive registered read result ---
  // Build a combinational mux over the read map using the *registered* address
  val hitVec  = readMap.map { case (_, (offset, _)) =>
    rdAddr === offset.U
  }.toSeq
  val anyHit  = hitVec.foldLeft(false.B)(_ || _)

  val rdData = readMap.foldLeft(0.U(dataBits.W)) { case (acc, (_, (offset, data))) =>
    Mux(rdAddr === offset.U, data, acc)
  }

  axi.data.valid      := rdPending
  axi.data.bits.data  := rdData
  axi.data.bits.resp  := Mux(anyHit, 0.U, 2.U)  // SLVERR on unknown address
  axi.data.bits.id    := rdId
  axi.data.bits.last  := true.B

  axi
}

/**
 * ConnectAxiWrite: Creates hardware for writing CSR registers via AXI.
 *
 * This function creates hardware inside the current module that implements
 * a register-mapped AXI write interface. When addr.valid and data.valid
 * are both asserted, the write is committed on the next clock edge and
 * resp.valid is asserted.
 *
 * @param addrBits  Number of address bits (also used as idBits)
 * @param writeMap  Map from register name to byte offset
 * @param write     The AxiWriteIO (from module perspective, Flipped = device)
 * @return          Tuple of (Map[name -> Bool write-enable], UInt write-data)
 */
def ConnectAxiWrite(
    addrBits: Int,
    writeMap: Map[String, Int],
    write: AxiWriteIO
): (Map[String, Bool], UInt) = {
  val dataBits = 32
  val idBits   = addrBits

  // --- Address/data channels: always ready ---
  write.addr.ready := true.B
  write.data.ready := true.B

  // --- Latch write address and data ---
  val wrPending  = RegInit(false.B)
  val wrAddr     = RegInit(0.U(dataBits.W))
  val wrData     = RegInit(0.U(dataBits.W))
  val wrId       = RegInit(0.U(idBits.W))

  // Capture when both addr and data are valid in the same cycle
  val doWrite = write.addr.valid && write.data.valid
  when(doWrite) {
    wrPending := true.B
    wrAddr    := write.addr.bits.addr
    wrData    := write.data.bits.data
    wrId      := write.addr.bits.id
  }.elsewhen(write.resp.valid && write.resp.ready) {
    wrPending := false.B
  }

  // --- Response channel ---
  val hitVec = writeMap.map { case (_, offset) =>
    wrAddr === offset.U
  }.toSeq
  val anyHit = hitVec.foldLeft(false.B)(_ || _)

  write.resp.valid      := wrPending
  write.resp.bits.resp  := Mux(anyHit, 0.U, 2.U)  // SLVERR on unknown address
  write.resp.bits.id    := wrId

  // --- Per-register write enables ---
  // A write enable is asserted during the cycle that wrPending goes high,
  // i.e., when doWrite fires for that register address.
  val writeEnables: Map[String, Bool] = writeMap.map { case (name, offset) =>
    name -> (doWrite && write.addr.bits.addr === offset.U)
  }

  (writeEnables, write.data.bits.data)
}

