/**
 * ConnectAxiWrite: Creates hardware for writing CSR registers via AXI.
 *
 * This function creates hardware inside the current module that implements
 * a register-mapped AXI write interface. When addr.valid and data.valid
 * are both asserted, the write is committed on the next clock edge, then
 * resp.valid is asserted in that cycle, and the write-enable signals fire
 * in that same registered cycle.
 *
 * Timing:
 *   - Cycle N: addr.valid && data.valid → write latched, wrPending:=1 at edge N
 *   - Cycle N+1: wrPending=1 → writes("x") fires, resp.valid=1
 *                register updates happen at edge N+1
 *   - Cycle N+2: resp consumed (if resp.ready), wrPending:=0
 *
 * @param addrBits  Number of address bits (also used as idBits)
 * @param writeMap  Map from register name to byte offset
 * @param write     The AxiWriteIO (from module perspective, Flipped = device)
 * @return          Tuple of (Map[name -> Bool write-enable], UInt write-data)
 */
def ConnectAxiWrite(
    addrBits: Int,
    writeMap: Map[String, Int],
    write: AxiWriteIO
): (Map[String, Bool], UInt) = {
  val dataBits = 32
  val idBits   = addrBits

  // --- Address/data channels: always ready ---
  write.addr.ready := true.B
  write.data.ready := true.B

  // --- Latch write address, data, and valid on doWrite ---
  val wrPending  = RegInit(false.B)
  val wrAddr     = RegInit(0.U(dataBits.W))
  val wrData     = RegInit(0.U(dataBits.W))
  val wrId       = RegInit(0.U(idBits.W))

  // Capture when both addr and data are valid in the same cycle.
  // A new doWrite takes priority over draining the existing response.
  val doWrite = write.addr.valid && write.data.valid
  when(doWrite) {
    wrPending := true.B
    wrAddr    := write.addr.bits.addr
    wrData    := write.data.bits.data
    wrId      := write.addr.bits.id
  }.elsewhen(write.resp.valid && write.resp.ready) {
    wrPending := false.B
  }

  // --- Response channel: driven from wrPending register ---
  val hitVec = writeMap.map { case (_, offset) =>
    wrAddr === offset.U
  }.toSeq
  val anyHit = hitVec.foldLeft(false.B)(_ || _)

  write.resp.valid      := wrPending
  write.resp.bits.resp  := Mux(anyHit, 0.U, 2.U)  // SLVERR on unknown address
  write.resp.bits.id    := wrId

  // --- Per-register write enables ---
  // Write enables fire during the cycle when wrPending=1, i.e., one cycle after
  // the write was received. This means the register being written (e.g., enable)
  // updates at the NEXT edge, and the target register (e.g., count) uses the
  // OLD value of enable during the same wrPending cycle — giving a 1-cycle gap
  // which is what the CounterAxiPeripheral test expects.
  val writeEnables: Map[String, Bool] = writeMap.map { case (name, offset) =>
    name -> (wrPending && wrAddr === offset.U)
  }

  (writeEnables, wrData)
}

