package peripheral

import chisel3._
import chisel3.util._
import bus._

/** Package-level utilities for connecting AXI CSR register maps.
  *
  * These functions create Chisel hardware (registers + combinational logic)
  * inside the current Module scope. They are intended to be called from
  * within a Module's body.
  */
package object peripheral {
  // (Package object contents are in this file but imported via `package peripheral`)
}

/** Peripheral interface helpers.
  *
  * Import with `import peripheral._` or use directly since they are in the
  * `peripheral` package object.
  */

/**
 * ConnectAxiRead: Creates hardware for reading CSR registers via AXI.
 *
 * When addr.valid is asserted, the address is sampled; one clock later
 * data.valid is asserted with the register value (or resp=2 for unknown
 * addresses).
 *
 * @param addrBits  idBits for the AXI ID field (also used to size the returned IO)
 * @param readMap   Map from register name to (byte offset, UInt data signal)
 * @return          An AxiReadIO Wire that can be bulk-connected to
 *                  the module's Flipped(AxiReadIO) port.
 */
object ConnectAxiRead {
  def apply(addrBits: Int, readMap: Map[String, (Int, UInt)]): AxiReadIO = {
    val fullAddrBits = 32
    val dataBits     = 32
    val idBits       = addrBits

    val axi = Wire(new AxiReadIO(fullAddrBits, dataBits, idBits))

    // Address channel: always ready
    axi.addr.ready := true.B

    // Pipeline registers: latch incoming address
    val rdPending = RegInit(false.B)
    val rdAddr    = RegInit(0.U(fullAddrBits.W))
    val rdId      = RegInit(0.U(idBits.W))

    when(axi.addr.valid) {
      rdPending := true.B
      rdAddr    := axi.addr.bits.addr
      rdId      := axi.addr.bits.id
    }.elsewhen(axi.data.valid && axi.data.ready) {
      rdPending := false.B
    }

    // Register data mux (combinational, reads current register values)
    val hitVec = readMap.map { case (_, (offset, _)) =>
      rdAddr === offset.U
    }.toSeq
    val anyHit = hitVec.foldLeft(false.B)(_ || _)

    val rdData = readMap.foldLeft(0.U(dataBits.W)) { case (acc, (_, (offset, data))) =>
      Mux(rdAddr === offset.U, data, acc)
    }

    axi.data.valid     := rdPending
    axi.data.bits.data := rdData
    axi.data.bits.resp := Mux(anyHit, 0.U(2.W), 2.U(2.W))
    axi.data.bits.id   := rdId
    axi.data.bits.last := true.B

    axi
  }
}

/**
 * ConnectAxiWrite: Creates hardware for writing CSR registers via AXI.
 *
 * Timing:
 *   - Cycle N: addr.valid && data.valid → latched (wrPending becomes 1 at edge N)
 *   - Cycle N+1: wrPending=1 → writes("x") true, resp.valid=1
 *                registers update at edge N+1
 *   - Cycle N+2: resp consumed (if resp.ready=1)
 *
 * @param addrBits  idBits for the AXI ID field
 * @param writeMap  Map from register name to byte offset
 * @param write     The AxiWriteIO port (device/slave perspective)
 * @return          Tuple of (Map[name -> Bool write-enable], UInt write-data)
 */
object ConnectAxiWrite {
  def apply(
      addrBits: Int,
      writeMap: Map[String, Int],
      write: AxiWriteIO
  ): (Map[String, Bool], UInt) = {
    val fullAddrBits = 32
    val dataBits     = 32
    val idBits       = addrBits

    // Addr and data channels always ready
    write.addr.ready := true.B
    write.data.ready := true.B

    // Latch write transaction
    val wrPending = RegInit(false.B)
    val wrAddr    = RegInit(0.U(fullAddrBits.W))
    val wrData    = RegInit(0.U(dataBits.W))
    val wrId      = RegInit(0.U(idBits.W))

    val doWrite = write.addr.valid && write.data.valid
    when(doWrite) {
      wrPending := true.B
      wrAddr    := write.addr.bits.addr
      wrData    := write.data.bits.data
      wrId      := write.addr.bits.id
    }.elsewhen(write.resp.valid && write.resp.ready) {
      wrPending := false.B
    }

    // Response channel
    val hitVec = writeMap.map { case (_, offset) =>
      wrAddr === offset.U
    }.toSeq
    val anyHit = hitVec.foldLeft(false.B)(_ || _)

    write.resp.valid     := wrPending
    write.resp.bits.resp := Mux(anyHit, 0.U(2.W), 2.U(2.W))
    write.resp.bits.id   := wrId

    // Per-register write enables: fire for one cycle when wrPending=1
    val writeEnables: Map[String, Bool] = writeMap.map { case (name, offset) =>
      name -> (wrPending && wrAddr === offset.U)
    }

